import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Column from './Column';
import './Board.css';

const API_URL = 'http://localhost:5000/api';

const Board = ({ onLogout }) => {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskAssignee, setNewTaskAssignee] = useState('');

  const fetchTasks = async () => {
    try {
      const response = await axios.get(`${API_URL}/tasks`);
      setTasks(response.data);
      setLoading(false);
    } catch (err) {
      setError('Failed to load tasks.');
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTasks();
  }, []);

  const handleCreateTask = async () => {
    if (!newTaskTitle.trim()) return;
    
    try {
      const response = await axios.post(`${API_URL}/tasks`, {
        title: newTaskTitle,
        description: '',
        status: 'todo',
        assignee: newTaskAssignee || 'Unassigned',
        priority: 'Medium'
      });
      setTasks([response.data, ...tasks]);
      setNewTaskTitle('');
      setNewTaskAssignee('');
    } catch (error) {
      console.error('Failed to create task:', error);
    }
  };

  const moveTask = async (taskId, newStatus) => {
    try {
      const task = tasks.find(t => t._id === taskId || t.id === taskId);
      if (!task) {
        console.error('Task not found:', taskId);
        return;
      }
      
      const response = await axios.put(`${API_URL}/tasks/${taskId}`, {
        ...task,
        status: newStatus
      });
      
      setTasks(tasks.map(t => (t._id === taskId || t.id === taskId) ? response.data : t));
    } catch (error) {
      console.error('Failed to move task:', error);
      alert('Failed to move task. Check console for details.');
    }
  };

  const columns = [
    { 
      id: 'todo', 
      title: 'To Do', 
      status: 'todo',
      tasks: tasks.filter(t => t.status === 'todo'),
      nextStatus: 'doing',
      nextLabel: '→ Doing'
    },
    { 
      id: 'doing', 
      title: 'Doing', 
      status: 'doing',
      tasks: tasks.filter(t => t.status === 'doing'),
      nextStatus: 'done',
      nextLabel: '→ Done'
    },
    { 
      id: 'done', 
      title: 'Done', 
      status: 'done',
      tasks: tasks.filter(t => t.status === 'done'),
      nextStatus: null,
      nextLabel: '✅ Complete'
    },
  ];

  if (loading) return (
    <div className="board-container">
      <div className="board-header">
        <h1>📋 <span>Sync</span>Board</h1>
        <button onClick={onLogout}>Logout</button>
      </div>
      <div style={{textAlign:'center', padding:'50px'}}>
        <h2>Loading tasks...</h2>
      </div>
    </div>
  );

  if (error) return (
    <div className="board-container">
      <div className="board-header">
        <h1>📋 <span>Sync</span>Board</h1>
        <button onClick={onLogout}>Logout</button>
      </div>
      <div style={{textAlign:'center', padding:'50px', color:'red'}}>
        <h2>⚠️ {error}</h2>
      </div>
    </div>
  );

  return (
    <div className="board-container">
      <div className="board-header">
        <h1>📋 <span>Sync</span>Board</h1>
        <button onClick={onLogout}>Logout</button>
      </div>
      
      <div className="task-input">
        <input
          type="text"
          placeholder="Task title..."
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleCreateTask()}
          className="task-title-input"
        />
        <input
          type="text"
          placeholder="Assign to..."
          value={newTaskAssignee}
          onChange={(e) => setNewTaskAssignee(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleCreateTask()}
          className="task-assignee-input"
        />
        <button onClick={handleCreateTask}>Add Task</button>
      </div>
      
      <div className="board-columns">
        {columns.map(col => (
          <Column 
            key={col.id} 
            title={col.title} 
            tasks={col.tasks} 
            onMoveTask={moveTask}
            nextStatus={col.nextStatus}
            nextLabel={col.nextLabel}
          />
        ))}
      </div>
    </div>
  );
};

export default Board;
